/* @lc app=leetcode id=3317 lang=kotlin */ class Solution { fun numberOfWays(n: Int, x: Int, y: Int): Int = 1_000_000_007L.let { M -> (1..n).fold(LongArray(n + 1).also { it[0] = 1 }) { prev, _ -> LongArray(n + 1) { j -> if (j == 0) 0L else (j * prev[j] + prev[j - 1]) % M } }.let { st -> (1..minOf(n, x)).fold(Triple(1L, 1L, 0L)) { (fall, yp, tot), k -> (fall * (x - k + 1) % M).let { f2 -> (yp * y % M).let { y2 -> Triple(f2, y2, (tot + f2 * st[k] % M * y2) % M) } } }.third.toInt() } } }